-- 25-nov Andreas: direct link to hidden projects must open (not listed anywhere)
create or replace function public.public_project_by_slug(p_slug text) returns json language sql stable security definer set search_path=public as $$ select row_to_json(t) from (select id,name,slug,location,zone,property_type,description,distance_beach,available_units,total_units,completion_percent,years_contract,years_extension,market_price,investor_price,price_currency,roi,investor_tiers,image,gallery,is_featured,status,sort_order,created_at,updated_at,bedrooms,bathrooms,area_m2,has_pool,amenities,furnishing,annual_rental_projection,completion_date,brochure_url,google_maps_url,floor_plans,construction_gallery,furnishing_items,is_hidden,visibility_status,land_size_m2,video_url,description_en,description_id,distance_beach_en,distance_beach_id,furnishing_en,furnishing_id,completion_date_en,completion_date_id,description_ro,distance_beach_ro,furnishing_ro,brochures,tenure,land_area_m2,area_m2_label,land_m2_label,view_type,walkthrough_url,already_rented,rent_currency,extension_years,lease_end_date,lease_end_date_en,lease_end_date_id,drive_renders_links from projects where slug = p_slug or p_slug like slug || '-%' order by (slug = p_slug) desc, length(slug) desc limit 1) t $$; grant execute on function public.public_project_by_slug(text) to anon, authenticated;
